le", "parameters": {"fileId": {"__rl": true, "cachedResultName": "Rules_of_Golf_Simplified.pdf", "cachedResultUrl": "https://drive.google.com/file/d/16ahWlNwBvd53xFHA4UUh6EbkFd8ogxBv/view?usp=drivesdk", "mode": "list", "value": "16ahWlNwBvd53xFHA4UUh6EbkFd8ogxBv"}, "operation": "download", "options": {}}, "position": [-100, -320], "type": "n8n-nodes-base.googleDrive", "typeVersion": 3}, {"id": "ad9a4d3c-ace1-428c-8957-edb456bf864f", "name": "Default Data Loader", "parameters": {"jsonData": "={{ $('Code').item.json.fullText }}", "jsonMode": "expressionData", "options": {"metadata": {"metadataValues": [{"name": "ruleNumber", "value": "={{ $json.ruleNumber }}"}]}}}, "position": [460, -180], "type": "@n8n/n8n-nodes-langchain.documentDefaultDataLoader", "typeVersion": 1.1}, {"id": "f6d44c38-8cb4-43ad-8130-7ab8cd142c9a", "name": "Extract from File", "parameters": {"operation": "pdf", "options": {}}, "position": [40, -320], "type": "n8n-nodes-base.extractFromFile", "typeVersion": 1}, {"id": "dfc604ab-b7bd-4a08-b65d-f8fe2c3b5c13", "name": "Code", "parameters": {"jsCode": "// n8n Code Node - Split Golf Rules
// This code takes the input text and splits it into separate items for each rule

// Get the input text from the first item
const inputText = $input.first().json.text;

// Split the text by "Rule" pattern, keeping the "Rule" text with each section
const ruleSections = inputText.split(/(?=Rule \d+)/);

// Remove the first empty element (everything before the first "Rule")
const cleanedSections = ruleSections.filter(section => section.trim().startsWith('Rule'));

// Create output items - one for each rule
const outputItems = cleanedSections.map((ruleText, index) => {
  // Extract rule number from the text
  const ruleMatch = ruleText.match(/Rule (\d+)/);
  const ruleNumber = ruleMatch ? ruleMatch[1] : (index + 1).toString();

  // Extract rule title (everything between "Rule X –" and the first numbered item)
  const titleMatch = ruleText.match(/Rule \d+ – (.+?)(?=\n1\.|\n\d+\.)/);
  const ruleTitle = titleMatch ? titleMatch[1].trim() : 'Unknown Rule';

  return {
    json: {
      ruleNumber: ruleNumber,
      ruleTitle: ruleTitle,
      fullText: ruleText.trim(),
      originalIndex: index
    }
  };
});

return outputItems;"}, "position": [180, -320], "type": "n8n-nodes-base.code", "typeVersion": 2}, {"id": "cc659be4-709e-4d59-a386-d7cc60166293", "name": "When chat message received", "parameters": {"options": {}}, "position": [-280, -1180], "type": "@n8n/n8n-nodes-langchain.chatTrigger", "typeVersion": 1.1, "webhookId": "79772045-628b-4cf6-b2ec-cecceca9fe24"}, {"credentials": {"openRouterApi": {"id": "fpo6OUh9TcHg29jk", "name": "OpenRouter account"}}, "id": "9f02235d-8c3f-4309-bd14-d4c6bcdfab11", "name": "GPT 4.1-mini", "parameters": {"options": {}}, "position": [-100, -1040], "type": "@n8n/n8n-nodes-langchain.lmChatOpenRouter", "typeVersion": 1}, {"credentials": {"cohereApi": {"id": "vCsqiDhFNdSGhDKu", "name": "CohereApi account"}}, "id": "dad869f9-4c1d-44a4-b523-31f007efccc7", "name": "Reranker Cohere", "parameters": {}, "position": [520, -1040], "type": "@n8n/n8n-nodes-langchain.rerankerCohere", "typeVersion": 1}, {"credentials": {"supabaseApi": {"id": "r1eLu64ie9Tz6yOK", "name": "Demo 2.22.25"}}, "id": "24cbdd3d-afee-46d2-83ef-888d432b4874", "name": "Upload to Supabase", "parameters": {"mode": "insert", "options": {"queryName": "match_documents"}, "tableName": {"__rl": true, "cachedResultName": "documents", "mode": "list", "value": "documents"}}, "position": [320, -320], "type": "@n8n/n8n-nodes-langchain.vectorStoreSupabase", "typeVersion": 1.3}, {"credentials": {"supabaseApi": {"id": "r1eLu64ie9Tz6yOK", "name": "Demo 2.22.25"}}, "id": "f80184cb-fc7e-40d7-bf2d-a723350c9f0f", "name": "Supabase Vector Store", "parameters": {"mode": "retrieve-as-tool", "options": {}, "tableName": {"__rl": true, "cachedResultName": "documents", "mode": "list", "value": "documents"}, "toolDescription": "Use this tool to search the database", "topK": 20, "useReranker": true}, "position": [360, -1180], "type": "@n8n/n8n-nodes-langchain.vectorStoreSupabase", "typeVersion": 1.3}, {"credentials": {"openRouterApi": {"id": "fpo6OUh9TcHg29jk", "name": "OpenRouter account"}}, "id": "de08fce1-