	transform: translateY(-2px);
}

.form-submit:hover::before {
	left: 100%;
}

.form-submit:active {
	transform: translateY(0);
	box-shadow: var(--shadow-sm);
}

/* Error Styling */
.form-error {
	color: var(--color-error);
	font-size: var(--font-size-error);
	margin-top: var(--space-1);
	display: flex;
	align-items: center;
	gap: var(--space-1);
}

.form-error::before {
	content: '⚠';
	font-size: var(--font-size-sm);
}

.form-input.error,
.form-select.error,
.form-textarea.error {
	border-color: var(--color-border-error);
	box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.1);
}

/* Test Notice Styling */
.test-notice {
	background: var(--color-test-notice-bg);
	color: var(--color-test-notice-text);
	border: 1px solid var(--color-test-notice-border);
	border-radius: var(--border-radius-md);
	padding: var(--padding-test-notice-vertical) var(--padding-test-notice-horizontal);
	margin-bottom: var(--space-6);
	font-size: var(--font-size-test-notice);
	display: flex;
	align-items: center;
	gap: var(--space-2);
}

.test-notice::before {
	content: 'ℹ';
	font-weight: var(--font-weight-bold);
	font-size: var(--font-size-base);
}

/* Progress Indicator */
.form-progress {
	height: 4px;
	background: var(--color-border-light);
	border-radius: var(--border-radius-sm);
	margin-bottom: var(--space-6);
	overflow: hidden;
}

.form-progress-bar {
	height: 100%;
	background: linear-gradient(90deg, var(--color-primary), var(--color-secondary));
	border-radius: var(--border-radius-sm);
	transition: width var(--transition-slow);
	width: 0%;
}

/* Loading State */
.form-loading {
	opacity: var(--opacity-disabled);
	pointer-events: none;
	position: relative;
}

.form-loading::after {
	content: '';
	position: absolute;
	top: 50%;
	left: 50%;
	width: 20px;
	height: 20px;
	margin: -10px 0 0 -10px;
	border: 2px solid var(--color-primary);
	border-top-color: transparent;
	border-radius: var(--border-radius-full);
	animation: spin 1s linear infinite;
}

@keyframes spin {
	to {
		transform: rotate(360deg);
	}
}

/* Responsive Design */
@media (max-width: 640px) {
	:root {
		--container-width: 100%;
		--padding-container-top: var(--space-4);
		--card-padding: var(--space-4);
		--font-size-header: var(--font-size-3xl);
	}

	.form-container {
		padding: var(--space-4) var(--space-3);
	}

	.form-submit {
