ons": {}}, "position": [-1776, 240], "type": "n8n-nodes-base.splitInBatches", "typeVersion": 3}, {"id": "af00819c-d885-4021-b693-06b9fb102112", "name": "Merge", "parameters": {}, "position": [-1008, 112], "type": "n8n-nodes-base.merge", "typeVersion": 3.2}, {"id": "83e234c1-9eb7-48dc-8956-a818fa338a8f", "name": "Create new backup folder", "parameters": {"name": "=n8n_{{$now.format('yyyy-MM-dd')}}", "operation": "create", "options": {"parentFolderId": ""}, "resource": "folder"}, "position": [-5056, 96], "type": "n8n-nodes-base.microsoftOneDrive", "typeVersion": 1}, {"id": "b1fda1d4-c8b6-4882-95a2-048400064677", "name": "Convert to JSON file", "parameters": {"mode": "each", "operation": "toJson", "options": {"fileName": "={{ $json.name }}", "format": true}}, "position": [-4160, 96], "type": "n8n-nodes-base.convertToFile", "typeVersion": 1.1}, {"id": "ea490d15-f4d0-485e-8686-deb9044012b6", "name": "Upload JSON to folder", "parameters": {"binaryData": true, "parentId": "={{ $('Create new backup folder').item.json.id }}"}, "position": [-3712, 96], "retryOnFail": false, "type": "n8n-nodes-base.microsoftOneDrive", "typeVersion": 1}, {"id": "21d3de22-1836-49cd-99b7-1fafb710294e", "name": "Filter backup folder", "parameters": {"jsCode": "// Filter backup folders older than 31 days - Clean version
const inputItems = $input.all();
const cutoffDate = DateTime.now().minus({ days: 31 });

console.log('Filtering backup folders older than 31 days');
console.log('Cutoff date:', cutoffDate.toISO());
console.log('Total folders found:', inputItems.length);

// Filter folders older than 8 days
const oldFolders = [];

// Process each input item
inputItems.forEach((item, index) => {
  try {
    if (item.json.lastModifiedDateTime) {
      const folderDate = DateTime.fromISO(item.json.lastModifiedDateTime);
      const isOld = folderDate < cutoffDate;

      console.log('Folder:', item.json.name || 'Unknown', 'Date:', folderDate.toFormat('dd/MM/yyyy'), 'Old:', isOld);

      if (isOld) {
        oldFolders.push(item);
      }
    }
  } catch (error) {
    console.log('Error parsing date for folder:', item.json.name, error);
  }
});

console.log('Old folders to delete:', oldFolders.length);
console.log('Recent folders to keep:', inputItems.length - oldFolders.length);

if (oldFolders.length > 0) {
  // FOUND OLD FOLDERS TO DELETE
  // Return ONLY the old folders with summary info in first item
  const result = oldFolders.map((folder, index) => {
    if (index === 0) {
      // First old folder gets summary metadata
      return {
        json: {
          id: folder.json.id,
          name: folder.json.name,
          lastModifiedDateTime: folder.json.lastModifiedDateTime,
          createdDateTime: folder.json.createdDateTime,
          size: folder.json.size,
          // Add metadata
          hasOldFolders: true,
          oldFoldersCount: oldFolders.length,
          totalFoldersChecked: inputItems.length,
          cutoffDate: cutoffDate.toISO()
        }
      };
    } else {
      // Other old folders keep original structure
      return {
        json: {
          id: folder.json.id,
          name: folder.json.name,
          lastModifiedDateTime: folder.json.lastModifiedDateTime,
          createdDateTime: folder.json.createdDateTime,
          size: folder.json.size
        }
      };
    }
  });

  console.log('Returning', result.length, 'OLD folders for deletion');
  return result;

} else {
  // NO OLD FOLDERS FOUND
  // Return single summary item
  console.log('No old folders found - all folders are recent');
  return [{
    json: {
      hasOldFolders: false,
      oldFoldersCount: 0,
      totalFoldersChecked: inputItems.length,
      cutoffDate: cutoffDate.toISO(),
      recentFoldersCount: inputItems.length,
      message: 'All backup folders are recent - no cleanup needed'
    }
  }];
}"}, "position": [-2848, 96], "type": "n8n-nodes-base.code", "typeVersion": 2}, {"id": "ba663fbc-67f2-47e3-a237-122aa555f7d8", "name": "Sticky Note - Overview", "parameters": {"color": 3, "content": "## 🗂️ Automated Workflow Backup Manager

### Goal:
This workflow automates the process of backing up your workflows in n8n by creating a new backup folder in OneDrive. It first retrieves existing workflows, deletes old backup folders if they exist, and then generates JSON files of the current workflows. An email notification confirms successful backups, ensuring you never lose your critical configurations.

### How it works:
- 🏁 **Schedule Trigger Daily**: Run the workflow daily.
- 🔄 **Retrieve Workflows**: Use the n8n node to collect all of your workflows.
- 💼 **Get Backup Folders**: Check for existing backup folders in OneDrive.
- 🗑️ **Delete Old Folder**: Remove the previous backup if it exists.
- 📧 **Prepare HTML Email**: Craft an email template to notify of successful backup.
- 📤 **Send HTML Success Email**: Notify you upon successful execution.
- 📁 **Create New Backup Folder**: Generate a new folder for the current backup.
- 📝 **Convert to JSON**: Transform workflows into JSON format for storage.
- 📤 **Upload JSON File**: Place the newly created JSON files into OneDrive.

### Parameters to Configure:
- OneDrive folder path for backups
- Email address for notifications
- Daily scheduling options

### Limitations / Gotchas:
- The workflow assumes an active OneDrive account.
- Ensure that folder permissions allow file creation and deletion.
- Sent A email using the Outlook Node

### Expected Result:
Upon execution, you'll receive a confirmation email, and the latest workflows will be securely backed up in the designated OneDrive folder.

## The green notes need action.
- For both you need to find the Folder ID. 
- Use the Search a Folder node to find the folder ID
