        'rgba(201, 203, 207, 0.8)'
      ],
      borderColor: 'rgba(0,0,0,0.1)',
      borderWidth: 1
    }]
  },
  options: {
    indexAxis: 'y',
    responsive: true,
    plugins: {
      legend: {
        display: false
      },
      title: {
        display: true,
        text: '📊 Company Market Cap Overview',
        font: {
